#include <vector>
using namespace std;
struct SegTree {
    vector<int>t;
    int n;
    SegTree(vector<int>&a):n(a.size()), t(4*a.size()) {
        build(a, 0, 0, n-1);
    }
    void build(vector<int>&a, int nd, int s, int e) {
        if (s==e) {
            t[nd]=a[s];
            return;
        }
        int m=(s+e)/2;
        build(a, 2*nd+1, s, m);
        build(a, 2*nd+2, m+1, e);
        t[nd]=t[2*nd+1]+t[2*nd+2];
    }
    int q(int nd, int s, int e, int l, int r) {
        if (r<s||e<l)return 0;
        if (l<=s&&e<=r)return t[nd];
        int m=(s+e)/2;
        return q(2*nd+1, s, m, l, r)+q(2*nd+2, m+1, e, l, r);
    }
};
